/// <summary>
/// CB256 update charge code line level.
/// </summary>
protected void endUpdate()
{
    next endUpdate();

    if (this.documentStatus() == DocumentStatus::PackingSlip)
    {
        VendPackingSlipTrans vendPackingSlipTransloc;
        PurchLine purchLineloc;

        ttsbegin;
        while select purchLineloc
            exists join vendPackingSlipTransloc
                where vendPackingSlipTransloc.VendPackingSlipJour == vendPackingSlipJour.RecId
                    && vendPackingSlipTransloc.InventTransId == purchLineloc.InventTransId
        {
            if(purchLineloc.PurchQty > purchLineloc.receivedInTotal()) //check if qty > received
            {
                METPurchLine metpurchline = METPurchLine::find(purchLineloc.RecId,true);
                if (metpurchline)
                {
                    metpurchline.ChangeReasonCode = METVendParameters::find().ChangeReasonCode;
                    metpurchline.doUpdate();
                }
            }
        }
        ttscommit;
    }
}
